// HasAuthor applies the HasEdge predicate on the "author" edge.
func HasAuthor() predicate.KnowledgeNote {
	return predicate.KnowledgeNote(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AuthorTable, AuthorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAuthorWith applies the HasEdge predicate on the "author" edge with a given conditions (other predicates).
func HasAuthorWith(preds ...predicate.User) predicate.KnowledgeNote {
	return predicate.KnowledgeNote(func(s *sql.Selector) {
		step := newAuthorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KnowledgeNote) predicate.KnowledgeNote {
	return predicate.KnowledgeNote(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KnowledgeNote) predicate.KnowledgeNote {
	return predicate.KnowledgeNote(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KnowledgeNote) predicate.KnowledgeNote {
	return predicate.KnowledgeNote(sql.NotPredicates(p))
}
